import math
def priority(task, state, b=1.0, M=100.0, m=2.0, a=1.0, v=1.0, s=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / (2.0 * est)
    lateness = max(0.0, ratio - 1.0)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'alignment':
        type_factor = a
    elif task.task_type == 'variant_calling':
        type_factor = v
    else:
        type_factor = s
    base = type_factor * tier * task.weight / est * (1.0 + b * wait / est)
    return base + M * lateness * lateness * (1.0 + wait / est)

