import math
def priority(task, state, w=1.0, k=0.5, b=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    slack = max(0.0, 2.0 * est - wait)
    return (task.weight ** w) / est * math.exp(-slack / (k * max(state.mean_est, 1e-6))) * (1.0 + b * wait / est)

def priority(task, state, b=2.0, c=1.0, a=1.0, w=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    qload = state.queue_work / max(state.capacity, 1e-6)
    base = (task.weight ** w) / est * (1.0 + b * ratio)
    if ratio >= c:
        return 1e6 + base
    return (task.weight ** w) / est * (1.0 + b * ratio * (1.0 + a * qload))

def priority(task, state, b=2.0, c=1.0, a=0.5):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    qload = state.queue_work / max(state.capacity, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    base = task.weight / est * (1.0 + b * ratio)
    if ratio >= 2.0:
        return 1e6 + base * (1.0 + c * ratio)
    return base * (1.0 + a * qload / mean_est)

def priority(task, state, b=2.0, g=10.0, p_premium=2.0, p_standard=1.0,
             m_align=1.0, m_variant=1.0, m_sv=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    excess = max(0.0, ratio - 2.0)
    tenant_mult = p_premium if task.tenant == 'premium' else p_standard
    if task.task_type == 'alignment':
        type_mult = m_align
    elif task.task_type == 'variant_calling':
        type_mult = m_variant
    else:
        type_mult = m_sv
    base = tenant_mult * type_mult * task.weight / est
    return base * (1.0 + b * ratio + g * excess)

