def priority(task, state, c=2.0, k=1.0, w=1.0, r=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    deadline = task.due if task.due > task.release else task.release + c * est
    slack = deadline - state.now
    expected_wait = state.queue_work / max(state.capacity, 1e-6)
    pred_slack = slack - k * expected_wait
    if pred_slack <= 0:
        return 1e9 + w * (0.0 - pred_slack) / est + 1.0 / max(est * cores, 1e-6)
    return w / max(pred_slack, 1e-6) + 1.0 / max(est * cores, 1e-6) + r * task.weight
```

