def priority(task, state, c=2.0, k=1.0, w=1.0, r=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    excess = wait - c * est
    if excess >= 0:
        return 1e9 + w * excess / est + 1.0 / max(est * cores, 1e-6)
    expected_wait = k * state.queue_work / max(state.capacity, 1e-6)
    projected_excess = wait + expected_wait - c * est
    if projected_excess >= 0:
        return 1e8 + w * projected_excess / est + 1.0 / max(est * cores, 1e-6)
    margin = c * est - wait
    return w / max(margin, 1e-6) + 1.0 / max(est * cores, 1e-6) + r * task.weight
