import math

def priority(task, state, k=1.0, w=1.0, r=1.0, premium_boost=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    deadline = task.due if task.due > task.release else task.release + 2.0 * est
    slack = deadline - state.now
    load = state.queue_work / max(state.capacity, 1e-6)
    weight = task.weight
    if task.tenant == 'premium':
        weight *= premium_boost
    if slack <= 0:
        return 1e9 + w * weight * (0.0 - slack) / est + 1.0 / max(est * cores, 1e-6)
    urgency = math.exp(-max(slack - k * load, -60.0) / max(w * est, 1e-6))
    return urgency * weight / max(est * cores, 1e-6) + r * wait / est
